    use Carbon\Carbon;

    $hour = Carbon::now('Pacific/Port_Moresby')->hour;

    if ($hour >= 5 && $hour < 12) {
        $greeting = 'Good Morning';
    } elseif ($hour >= 12 && $hour < 17) {
        $greeting = 'Good Afternoon';
    } elseif ($hour >= 17 && $hour < 21) {
        $greeting = 'Good Evening';
    } else {
        $greeting = 'Good Night';
    }

    $userName = Auth::check() ? Auth::user()->name : 'Guest';
    @endphp

